<?php $labels=['draft'=>'Rascunho','sent'=>'Enviado','viewed'=>'Visualizado','signed'=>'Assinado','cancelled'=>'Cancelado'];$models=['fixed_plus_percentage'=>'Mensalidade + percentual','split_only'=>'Somente split']; ?>
<div class="page-header"><div><p class="eyebrow">ADM Central · Franquia</p><h1>Contratos</h1><p><strong><?= $escape((string)$organization['display_name']) ?></strong> · <?= $escape((string)$organization['cnpj']) ?></p></div><div class="actions"><a class="button button-primary" href="<?= $escape($basePath) ?>/admin/franchise-applications/<?= (int)$application['id'] ?>/contracts/create"><i class="fa-solid fa-file-circle-plus"></i> Vincular contrato</a><a class="button button-secondary" href="<?= $escape($basePath) ?>/admin/organizations"><i class="fa-solid fa-arrow-left"></i> Voltar</a></div></div>
