<?php if($contracts===[]):?><div class="empty-state"><i class="fa-solid fa-file-signature"></i><strong>Nenhum contrato vinculado</strong><p>Use o botão acima para gerar o primeiro contrato desta franquia.</p></div><?php else:?><div class="table-responsive"><table><thead><tr><th>Contrato</th><th>Tipo</th><th>Modelo comercial</th><th>Vigência</th><th>Situação</th><th>Assinatura</th><th>Ação</th></tr></thead><tbody><?php foreach($contracts as$c):?><tr><td><strong>#<?= (int)($c['contract_number']??1) ?> · <?= $escape((string)$c['title']) ?></strong><small class="d-block meta"><?= $escape(date('d/m/Y H:i',strtotime((string)$c['created_at']))) ?></small></td><td><?= ($c['contract_type']??'new')==='renewal'?'Renovação':'Novo' ?></td><td><?= $escape($models[$c['commercial_model']]??'Legado') ?></td><td><?= $c['valid_from']?$escape(date('d/m/Y',strtotime((string)$c['valid_from']))):'Sem início' ?> — <?= $c['valid_until']?$escape(date('d/m/Y',strtotime((string)$c['valid_until']))):'indeterminada' ?></td><td><span class="badge <?= $c['status']==='signed'?'badge-success':'badge-warning' ?>"><?= $escape($labels[$c['status']]??(string)$c['status']) ?></span></td><td><?= $c['signed_at']?$escape(date('d/m/Y H:i',strtotime((string)$c['signed_at']))):'Pendente' ?></td><td><a class="button button-secondary button-icon" title="Abrir contrato" href="<?= $escape($basePath) ?>/admin/franchise-contracts/<?= (int)$c['id'] ?>"><i class="fa-solid fa-eye"></i></a><?php if($c['status']==='signed'):?><a class="button button-secondary button-icon" title="Renovar contrato" href="<?= $escape($basePath) ?>/admin/franchise-applications/<?= (int)$application['id'] ?>/contracts/create?renew_from=<?= (int)$c['id'] ?>"><i class="fa-solid fa-rotate"></i></a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
